package thaumcraft.port;

import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import thaumcraft.port.aspect.Aspect;
import thaumcraft.port.essentia.*;

final class EssentiaTest {
    @Test void simulationCannotChangeStorage(){var tank=new EssentiaTank(250);assertEquals(250,tank.insert(Aspect.AIR,999,false,true));assertEquals(0,tank.amount());tank.insert(Aspect.AIR,200,false,false);assertEquals(50,tank.insert(Aspect.AIR,100,false,true));assertEquals(200,tank.extract(Aspect.AIR,500,true));assertEquals(200,tank.amount());}
    @Test void rejectsMixingAndFilterMismatch(){var tank=new EssentiaTank(250);assertTrue(tank.filter(Aspect.FIRE));assertEquals(0,tank.insert(Aspect.WATER,10,false,false));assertEquals(10,tank.insert(Aspect.FIRE,10,false,false));assertFalse(tank.filter(Aspect.AIR));assertEquals(0,tank.extract(Aspect.WATER,10,false));assertEquals(10,tank.amount());}
    @Test void emptyJarRetainsLabel(){var tank=new EssentiaTank(250);tank.filter(Aspect.FIRE);tank.insert(Aspect.FIRE,10,false,false);tank.extract(Aspect.FIRE,10,false);assertNull(tank.aspect());assertEquals(Aspect.FIRE,tank.filter());assertEquals(64,tank.suction(false));}
    @Test void capacityAndOverflowUseOriginalRules(){var tank=new EssentiaTank(250);assertEquals(250,tank.insert(Aspect.AIR,Integer.MAX_VALUE,false,false));assertEquals(0,tank.suction(false));assertEquals(32,tank.suction(true));assertEquals(Integer.MAX_VALUE,tank.insert(Aspect.AIR,Integer.MAX_VALUE,true,false));assertEquals(250,tank.amount());assertEquals(0,tank.insert(Aspect.EARTH,1,true,false));}
    @Test void suctionPriorities(){var jar=new EssentiaTank(250);assertEquals(32,jar.suction(false));jar.filter(Aspect.FIRE);assertEquals(64,jar.suction(false));assertEquals(48,jar.suction(true));jar.insert(Aspect.FIRE,250,false,false);assertEquals(0,jar.suction(false));assertEquals(32,jar.suction(true));assertEquals(48,jar.minimum(true));}
    @Test void restoreClampsAndRejectsCorruptMixing(){var jar=new EssentiaTank(128);jar.restore(Aspect.AIR,Integer.MAX_VALUE,Aspect.EARTH);assertEquals(128,jar.amount());assertNull(jar.filter());jar.restore(null,999,Aspect.EARTH);assertEquals(0,jar.amount());assertEquals(Aspect.EARTH,jar.filter());jar.restore(Aspect.AIR,-20,null);assertNull(jar.aspect());}
    @Test void repeatedMovesConserveEveryUnit(){var random=new Random(61821);var jars=new EssentiaTank[12];for(int i=0;i<jars.length;i++){jars[i]=new EssentiaTank(250);jars[i].insert(Aspect.FIRE,i*19,false,false);}int initial=Arrays.stream(jars).mapToInt(EssentiaTank::amount).sum();for(int i=0;i<10000;i++){var from=jars[random.nextInt(jars.length)];var to=jars[random.nextInt(jars.length)];int count=Math.min(from.extract(Aspect.FIRE,random.nextInt(300),true),to.insert(Aspect.FIRE,300,false,true));from.extract(Aspect.FIRE,count,false);assertEquals(count,to.insert(Aspect.FIRE,count,false,false));}assertEquals(initial,Arrays.stream(jars).mapToInt(EssentiaTank::amount).sum());}
    @Test void tubeSuctionDecaysAndRestrictorHalves(){var demand=new SuctionRules.Demand(Aspect.AIR,64,false);assertEquals(63,SuctionRules.calculate(null,null,false,List.of(demand)).strength());assertEquals(32,SuctionRules.calculate(null,null,true,List.of(demand)).strength());for(int i=0;i<80;i++)demand=SuctionRules.calculate(null,null,false,List.of(demand));assertEquals(0,demand.strength());}
    @Test void tubeRejectsIncompatibleDemand(){var neighbours=List.of(new SuctionRules.Demand(Aspect.AIR,64,false),new SuctionRules.Demand(Aspect.WATER,48,false));assertEquals(Aspect.WATER,SuctionRules.calculate(null,Aspect.WATER,false,neighbours).aspect());assertEquals(0,SuctionRules.calculate(Aspect.FIRE,null,false,neighbours).strength());}
    @Test void ventingHonoursPressureAndFilterException(){var here=new SuctionRules.Demand(Aspect.FIRE,31,false);assertTrue(SuctionRules.conflicts(here,new SuctionRules.Demand(Aspect.AIR,30,false)));assertTrue(SuctionRules.conflicts(here,new SuctionRules.Demand(Aspect.AIR,31,false)));assertFalse(SuctionRules.conflicts(here,new SuctionRules.Demand(Aspect.AIR,32,false)));assertFalse(SuctionRules.conflicts(here,new SuctionRules.Demand(Aspect.AIR,31,true)));}
    @Test void smeltingConservesAspectsIncludingPollution(){for(int tier=0;tier<3;tier++){var state=new SmelterState();var random=new Random(800+tier);int pollution=state.smelt(Map.of(Aspect.AIR,100,Aspect.FLUX,100),tier,random::nextDouble);assertTrue(pollution>0);assertEquals(200,state.total()+pollution);}}
    @Test void smelterCannotOverfillOrConsumeUnknown(){var state=new SmelterState();assertEquals(-1,state.smelt(Map.of(),0,()->0));assertEquals(-1,state.smelt(Map.of(Aspect.AIR,257),0,()->0));assertEquals(0,state.total());assertEquals(0,state.smelt(Map.of(Aspect.AIR,256),0,()->0));assertFalse(state.fits(Map.of(Aspect.FIRE,1)));assertEquals(-1,state.smelt(Map.of(Aspect.FIRE,1),2,()->0));assertEquals(256,state.total());}
    @Test void originalEfficiencyTiersAndFluxPenalty(){assertEquals(1,new SmelterState().smelt(Map.of(Aspect.AIR,1),0,()->.85));assertEquals(0,new SmelterState().smelt(Map.of(Aspect.AIR,1),1,()->.85));assertEquals(1,new SmelterState().smelt(Map.of(Aspect.FLUX,1),2,()->.7));assertEquals(0,new SmelterState().smelt(Map.of(Aspect.AIR,1),2,()->.94));}
    @Test void smelterRestoreAndExtractionStayBounded(){var state=new SmelterState();state.restore(Map.of(Aspect.AIR,Integer.MAX_VALUE,Aspect.WATER,20));assertEquals(256,state.total());for(int i=0;i<256;i++)assertTrue(state.take(Aspect.AIR));assertFalse(state.take(Aspect.AIR));assertTrue(state.aspects().isEmpty());}
}
